class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self, head=None):
        self.head = head

    def add_node(self, value):
        new_node = Node(value)
        if self.head is None:
            self.head = new_node
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = new_node

    def iterate(self):
        current = self.head
        while current is not None:
            print(current.value)
            current = current.next

ll = LinkedList()
for v in [0, 2, 3, 4]:
    ll.add_node(v)
ll.iterate()
